import warnings

class InstructionRegistry:
    def __init__(self):
        self.instructions = {}

    def register(self, name, opcode, length, encoding):
        if name in self.instructions:
            warnings.warn(f"Instruction {name} already exists in the registry. Overwriting.")
        self.instructions[name] = {"opcode": opcode, "length": length, "encoding": encoding}

    def get(self, name):
        return self.instructions.get(name)

    def list(self):
        return list(self.instructions.keys())

    def dump(self):
        for name, info in self.instructions.items():
            print(f"{name}: {info['opcode']} ({info['length']} bytes, {info['encoding']})")

