        if self.manifest is None:
            self.manifest = json.dumps({key: value})
        else:
            data = json.loads(self.manifest)
            data[key] = value
            self.manifest = json.dumps(data)
        self.write(self.manifest)

    def delete(self, key):
        if self.manifest is None:
            return
        data = json.loads(self.manifest)
        if key in data:
            del data[key]
            self.manifest = json.dumps(data)
            self.write(self.manifest)

    def items(self):
        if self.manifest is None:
            return []
        return json.loads(self.manifest).items()
