import argparse
import git
import os
import subprocess
import sys

class MkDocsVersionManager:
    def __init__(self, repo_path, docs_path, version_path):
        self.repo_path = repo_path
        self.docs_path = docs_path
        self.version_path = version_path
        self.branches = self.get_branches()

    def get_branches(self):
        try:
            return [branch.name for branch in git.Repo(self.repo_path).branches]
        except git.InvalidGitRepositoryError:
            return []

    def get_current_branch(self):
        return git.Repo(self.repo_path).active_branch.name

    def checkout_branch(self, branch_name):
        subprocess.run(['git', 'checkout', branch_name], cwd=self.repo_path)

    def create_branch(self, branch_name):
        subprocess.run(['git', 'branch', branch_name], cwd=self.repo_path)

    def delete_branch(self, branch_name):
        subprocess.run(['git', 'branch', '-D', branch_name], cwd=self.repo_path)

    def create_docs(self, branch_name):
        os.makedirs(os.path.join(self.version_path, branch_name), exist_ok=True)
        subprocess.run(['mkdocs', 'new', branch_name], cwd=self.version_path)
        subprocess.run(['mkdocs','serve', '--dev-addr=0.0.0.0:8000', '--clean', '--theme=readthedocs'], cwd=self.version_path)

    def update_docs(self, branch_name):
        subprocess.run(['git', 'pull', '--rebase'], cwd=self.repo_path)
        subprocess.run(['mkdocs', 'build'], cwd=self.version_path)

    def delete_docs(self, branch_name):
        subprocess.run(['rm', '-rf', os.path.join(self.version_path, branch_name)], cwd=self.version_path)

def main():
    parser = argparse.ArgumentParser(description='MkDocs version manager')
    subparsers = parser.add_subparsers(dest='command')

    create_parser = subparsers.add_parser('create')
    create_parser.add_argument('-b', '--branch', required=True, help='Branch name')
    create_parser.add_argument('-v', '--version', required=True, help='Documentation version')

    delete_parser = subparsers.add_parser('delete')
    delete_parser.add_argument('-b', '--branch', required=True, help='Branch name')

    update_parser = subparsers.add_parser('update')
    update_parser.add_argument('-b', '--branch', required=True, help='Branch name')

    args = parser.parse_args()

    if args.command == 'create':
        manager = MkDocsVersionManager(repo_path='./repo', docs_path='./docs', version_path='./versions')
        manager.create_docs(args.branch)
    elif args.command == 'delete':
        manager = MkDocsVersionManager(repo_path='./repo', docs_path='./docs', version_path='./versions')
        manager.delete_docs(args.branch)
    elif args.command == 'update':
        manager = MkDocsVersionManager(repo_path='./repo', docs_path='./docs', version_path='./versions')
        manager.update_docs(args.branch)
    else:
        parser.print_help()

if __name__ == '__main__':
    main()

