import numpy as np
import scipy.signal as signal
import matplotlib.pyplot as plt
from scipy import fft
from scipy.signal import welch
from scipy.stats import kurtosis, skew
from scipy import signal

def extract_time_domain_features(signal):
    # Spike count
    spike_count = np.sum(signal > 0)

    # Burst duration
    burst_start = np.where(np.diff(np.sign(signal)) > 0)[0]
    burst_end = np.where(np.diff(np.sign(signal)) < 0)[0]
    if len(burst_start) < len(burst_end):
        burst_start = np.append(burst_start, len(signal))
    elif len(burst_end) < len(burst_start):
        burst_end = np.append(burst_end, len(signal))
    burst_duration = np.mean(np.diff(np.array([burst_start, burst_end])))
    return spike_count, burst_duration

