import random
from text_maze import generate_maze, display_maze

def generate_maze_custom(width, height, start, finish):
    maze = generate_maze(width, height)
    maze[start[0]][start[1]] = 'S'
    maze[finish[0]][finish[1]] = 'F'
    return maze

def display_custom_maze(maze):
    print('\033[1;1H') # Move the cursor to the top left
    for row in maze:
        print(' '.join(row))

def solve_maze(maze):
    start = None
    finish = None
    for i in range(len(maze)):
        for j in range(len(maze[0])):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'F':
                finish = (i, j)
    return solve_maze_recursive(maze, start, finish)

def solve_maze_recursive(maze, current, finish):
    if current == finish:
        return True
    maze[current[0]][current[1]] = 'P'
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    for direction in directions:
        new_x = current[0] + direction[0]
        new_y = current[1] + direction[1]
        if (new_x >= 0 and new_x < len(maze) and
            new_y >= 0 and new_y < len(maze[0]) and
            maze[new_x][new_y]!= 'W' and
            maze[new_x][new_y]!= 'P'):
            if solve_maze_recursive(maze, (new_x, new_y), finish):
                return True
    maze[current[0]][current[1]] =''
    return False

def main():
    width = int(input('Enter the width of the maze: '))
    height = int(input('Enter the height of the maze: '))
    start_x = int(input('Enter the x-coordinate of the start: '))
    start_y = int(input('Enter the y-coordinate of the start: '))
    finish_x = int(input('Enter the x-coordinate of the finish: '))
    finish_y = int(input('Enter the y-coordinate of the finish: '))
    maze = generate_maze_custom(width, height, (start_x, start_y), (finish_x, finish_y))
    display_custom_maze(maze)
    print("Path:")
    print(solve_maze(maze))

