def compile_solc(source_code, source_map=False, optimize=False, optimizer_runs=200):
    solc_instance = solc.compile_files([source_code], 
                                      import_remappings="", 
                                      optimize=optimize, 
                                      optimizer_runs=optimizer_runs, 
                                      output_format="json", 
                                      solc_binary="solc", 
                                      source_map=source_map)
    return solc_instance

def compile_solc_manual(source_code, source_map=False, optimize=False, optimizer_runs=200):
    solc_binary = "solc"
    if optimize:
        command = f"{solc_binary} --optimize --runs {optimizer_runs} --{'' if source_map else 'no'}source-map {source_code}"
    else:
        command = f"{solc_binary} --{'' if source_map else 'no'}source-map {source_code}"

    try:
        output = subprocess.check_output(command, shell=True)
        return output.decode('utf-8')
    except Exception as e:
        print(e)

