    return subprocess.check_output(['solc', '--version']).decode('utf-8').strip()

def compile_sol(file_path, contract_name, source_map=False, optimize=False, optimizer_runs=200):
    with open(file_path, 'r') as f:
        source_code = f.read()

    solc_instance = compile_solc(source_code, source_map, optimize, optimizer_runs)
    return solc_instance[contract_name]

