    return parsed_message

def print_hl7_message(message):
    for segment in message.segments:
        print(f"{segment[0]} : {segment[1]}")
    for segment in message.segments:
        for field in segment:
            print(f"{segment[0]}::{field} : {segment[field]}")

def write_hl7_message(message):
    # Define the message structure
    message_str = "MSH|^~\\&|Patient|Patient|ORDER|Lab|20230525||ORU^R01|12345|P|2.5|||AL|||"
    for segment in message.segments:
        message_str += "\r"
        message_str += f"{segment[0]}:"
        for field in segment:
            message_str += f"{field}::{segment[field]}|"
        message_str = message_str.rstrip("|")
    return message_str

