# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class WyzeAPI:
    def __init__(self, api_key, device_id, secret_key):
        self.api_key = api_key
        self.device_id = device_id
        self.secret_key = secret_key
        self.base_url = "https://api.wyze.com/v2"

    def authenticate(self):
        auth_data = {
            "grant_type": "client_credentials",
            "device_id": self.device_id
        }

        auth_response = requests.post(self.base_url + "/access_token", data=json.dumps(auth_data), headers={"Content-Type": "application/json"}, auth=HTTPBasicAuth(self.api_key, self.secret_key))

        if auth_response.status_code == 200:
            return auth_response.json()["access_token"]
        else:
            raise Exception("Failed to obtain access token")

    def get_access_token(self):
        return self.authenticate()

    def get_devices(self, access_token):
        headers = {"Authorization": f"Bearer {access_token}"}
        devices_response = requests.get(self.base_url + "/devices", headers=headers)

        if devices_response.status_code == 200:
            return devices_response.json()["data"]
        else:
            raise Exception("Failed to retrieve devices")

