import logging
import dns.resolver
import dns.reversename
import requests

# Configuration
pdns_api_url = 'https://yourpdns.com/api/v1/servers/yourpdnsserver'
pdns_api_key = 'yourpdnsapikey'

def perform(domain, validation_name, validation_value, validation_type):
    # Validate domain
    try:
        dns.resolver.resolve(domain, 'SOA')
    except dns.resolver.NoAnswer:
        logging.error(f"Domain {domain} does not exist")
        return False
    except dns.resolver.NXDOMAIN:
        logging.error(f"Domain {domain} does not exist")
        return False

    # Validate name server
    try:
        dns.resolver.resolve(domain, 'NS')
    except dns.resolver.NoAnswer:
        logging.error(f"Domain {domain} does not have NS records")
        return False
    except dns.resolver.NXDOMAIN:
        logging.error(f"Domain {domain} does not exist")
        return False

    # Validate name server has PowerDNS API access
    pdns_server = dns.resolver.resolve(domain, 'NS')[0].target.to_text()
    if not has_pdns_access(pdns_server):
        logging.error(f"Name server {pdns_server} does not have PowerDNS API access")
        return False

    # Validate record
    try:
        dns.resolver.resolve(validation_name, validation_type)
    except dns.resolver.NoAnswer:
        logging.info(f"No existing record for {validation_name}")
    except dns.resolver.NXDOMAIN:
        logging.info(f"No existing record for {validation_name}")

    # Set up PowerDNS API
    headers = {'X-API-KEY': pdns_api_key}
    data = {'content': validation_value, 'type': validation_type}

    # Create record
    try:
        response = requests.post(f'{pdns_api_url}/records', headers=headers, json=data)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        logging.error(f"Failed to create record {validation_name}: {e}")
        return False

    return True

def has_pdns_access(server):
    # Validate name server
    try:
        dns.resolver.resolve(server, 'A')
    except dns.resolver.NoAnswer:
        logging.error(f"Name server {server} does not have A records")
        return False
    except dns.resolver.NXDOMAIN:
        logging.error(f"Name server {server} does not exist")
        return False

    # Validate PowerDNS API access
    try:
        response = requests.get(f'http://{server}:80/api/v1/servers/localhost/keys')
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        logging.error(f"Failed to access PowerDNS API on {server}: {e}")
        return False

    return True

