def parse_address(address):
    address = address.lower()
    match = re.match(r"(\d+) (\w+) (\w+) (\w+)", address)
    if match:
        street_number = match.group(1)
        street_name = match.group(2)
        street_type = match.group(3)
        street_direction = match.group(4)
        return f"{street_number} {street_name} {street_type} {street_direction}"
    else:
        return address

def format_address(address):
    address = address.lower()
    address = re.sub(r"(\d+) (\w+) (\w+) (\w+)", r"\g<1> \g<2> \g<3> \g<4>", address)
    if "st" in address:
        address = re.sub(r"(\d+) (street)", r"\g<1> St", address)
    elif "ave" in address:
        address = re.sub(r"(\d+) (avenue)", r"\g<1> Ave", address)
    elif "blvd" in address:
        address = re.sub(r"(\d+) (boulevard)", r"\g<1> Blvd", address)
    elif "dr" in address:
        address = re.sub(r"(\d+) (drive)", r"\g<1> Dr", address)
    elif "ln" in address:
        address = re.sub(r"(\d+) (lane)", r"\g<1> Ln", address)
    elif "rd" in address:
        address = re.sub(r"(\d+) (road)", r"\g<1> Rd", address)
    elif "st" in address:
